+        font-size: 0.85rem;
+        font-weight: 700;
+        letter-spacing: 0.16em;
+        text-transform: uppercase;
+      }
+
+      h1 {
+        margin: 0;
+        font-size: clamp(2.25rem, 7vw, 4.75rem);
+        line-height: 1;
+      }
+
+      .intro {
+        max-width: 42rem;
+        margin: 1rem auto 0;
+        color: var(--muted);
+        font-size: 1.1rem;
+      }
+
+      .faq {
+        display: grid;
+        gap: 1rem;
+      }
+
+      .example {
+        overflow: clip;
+        border: 1px solid rgba(255, 255, 255, 0.09);
+        border-radius: 1.25rem;
+        background: linear-gradient(145deg, rgba(21, 31, 51, 0.94), rgba(12, 18, 30, 0.94));
+        box-shadow: 0 1.25rem 3.5rem var(--shadow);
+      }
+
+      .question {
+        display: flex;
+        align-items: center;
+        justify-content: space-between;
+        width: 100%;
+        gap: 1rem;
+        border: 0;
+        padding: 1.25rem 1.4rem;
+        color: inherit;
+        background: transparent;
+        font: inherit;
+        font-size: 1.05rem;
+        font-weight: 800;
+        text-align: left;
+        cursor: pointer;
+      }
+
+      .question:hover {
+        background: rgba(255, 255, 255, 0.035);
+      }
+
+      .question:focus-visible {
+        outline: 3px solid var(--ring);
+        outline-offset: -3px;
+      }
+
+      .icon {
+        display: inline-grid;
+        flex: 0 0 auto;
+        width: 2rem;
+        height: 2rem;
+        place-items: center;
+        border-radius: 999px;
+        color: #06110f;
+        background: var(--accent);
+        transition: transform 180ms ease, background-color 180ms ease;
+      }
+
+      .question[aria-expanded="true"] .icon {
+        transform: rotate(45deg);
+        background: var(--accent-strong);
+      }
+
+      .details {
+        padding: 0 1.4rem 1.35rem;
+        color: var(--muted);
+      }
+
+      .details p {
+        max-width: 68ch;
+        margin: 0;
+      }
+
+      [hidden] {
+        display: none;
+      }
+
+      @media (prefers-reduced-motion: reduce) {
+        .icon {
+          transition: none;
+        }
+      }
+    </style>
+  </head>
+  <body>
+    <main>
+      <section class="hero" aria-labelledby="page-title">
+        <p class="eyebrow">Curious cat care</p>
+        <h1 id="page-title">Cat FAQ</h1>
+        <p class="intro">
+          Quick answers to common questions about cat behavior, health, feeding,
+          and everyday care.
+        </p>
+      </section>
+
+      <section class="faq" aria-label="Frequently asked questions about cats">
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="answer-why-purr">
+            <span>Why do cats purr?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="answer-why-purr" hidden>
+            <p>
+              Cats often purr when they feel relaxed, but they may also purr when
+              seeking comfort, recovering from stress, or communicating with people.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="answer-feeding">
+            <span>How often should I feed my cat?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="answer-feeding" hidden>
+            <p>
+              Most adult cats do well with two measured meals per day, though kittens,
+              seniors, and cats with medical needs may require a different schedule.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="answer-kneading">
+            <span>What does kneading mean?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="answer-kneading" hidden>
+            <p>
+              Kneading is a common comfort behavior. Many cats press their paws into
+              soft surfaces when they are content, settling down, or marking a cozy spot.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="answer-scratching">
+            <span>How can I reduce furniture scratching?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="answer-scratching" hidden>
+            <p>
+              Provide sturdy scratching posts near favorite furniture, reward your cat
+              for using them, and keep claws trimmed. Scratching is natural, so redirect
+              it rather than trying to stop it entirely.
+            </p>
+          </div>
+        </div>
+
+        <div class="example">
+          <button class="question" type="button" aria-expanded="false" aria-controls="answer-vet">
+            <span>When should a cat see a veterinarian?</span>
+            <span class="icon" aria-hidden="true">+</span>
+          </button>
+          <div class="details" id="answer-vet" hidden>
+            <p>
+              Schedule routine wellness visits at least once a year. Seek care promptly
+              for appetite changes, breathing trouble, repeated vomiting, litter box
+              changes, injury, or sudden behavior shifts.
+            </p>
+          </div>
+        </div>
+      </section>
+    </main>
+
+    <script>
+      const questions = document.querySelectorAll(".question");
+
+      questions.forEach((question) => {
+        question.addEventListener("click", () => {
+          const answerId = question.getAttribute("aria-controls");
+          const answer = document.getElementById(answerId);
+          const isExpanded = question.getAttribute("aria-expanded") === "true";
+
+          question.setAttribute("aria-expanded", String(!isExpanded));
+          answer.hidden = isExpanded;
+        });
+      });
+    </script>
+  </body>
+</html>
*** End Patch
