        max-width: 42rem;
        margin: 1rem auto 0;
        color: var(--muted);
        font-size: 1.1rem;
      }

      .faq {
        display: grid;
        gap: 1rem;
      }

      .example {
        overflow: clip;
        border: 1px solid rgba(255, 255, 255, 0.09);
        border-radius: 1.25rem;
        background: linear-gradient(145deg, rgba(21, 31, 51, 0.94), rgba(12, 18, 30, 0.94));
        box-shadow: 0 1.25rem 3.5rem var(--shadow);
      }

      .question {
        display: flex;
        align-items: center;
        justify-content: space-between;
        width: 100%;
        gap: 1rem;
        border: 0;
        padding: 1.25rem 1.4rem;
        color: inherit;
        background: transparent;
        font: inherit;
        font-size: 1.05rem;
        font-weight: 800;
        text-align: left;
        cursor: pointer;
      }

      .question:hover {
        background: rgba(255, 255, 255, 0.035);
