           </div>
         </div>

         <div class="example">
           <button class="question" type="button" aria-expanded="false" aria-controls="answer-vet">
             <span>When should a cat see a veterinarian?</span>
             <span class="icon" aria-hidden="true">+</span>
           </button>
           <div class="details" id="answer-vet" hidden>
             <p>
               Schedule routine wellness visits at least once a year. Seek care promptly
               for appetite changes, breathing trouble, repeated vomiting, litter box
               changes, injury, or sudden behavior shifts.
             </p>
           </div>
         </div>
       </section>
     </main>

     <script>
       const questions = document.querySelectorAll(".question");

       questions.forEach((question) => {
         question.addEventListener("click", () => {
           const answerId = question.getAttribute("aria-controls");
           const answer = document.getElementById(answerId);
           const isExpanded = question.getAttribute("aria-expanded") === "true";

           question.setAttribute("aria-expanded", String(!isExpanded));
           answer.hidden = isExpanded;
         });
       });
     </script>
   </body>
 </html>

')
